namespace MyAgents.Runtime.Workers;

/// <summary>Polling, lease, and retry settings for a hosted run worker.</summary>
public sealed class AgentRunWorkerOptions
{
    /// <summary>Maximum active runs handled by this worker service instance. Defaults to one.</summary>
    public int MaxConcurrentRuns { get; set; } = 1;

    /// <summary>Optional stable worker identifier. A unique process identifier is generated by default.</summary>
    public string? WorkerId { get; set; }

    /// <summary>Delay between empty queue polls. Defaults to one second.</summary>
    public TimeSpan IdlePollInterval { get; set; } = TimeSpan.FromSeconds(1);

    /// <summary>Duration for each backend lease. Defaults to thirty seconds.</summary>
    public TimeSpan LeaseDuration { get; set; } = TimeSpan.FromSeconds(30);

    /// <summary>Heartbeat interval. Must be shorter than <see cref="LeaseDuration"/>.</summary>
    public TimeSpan LeaseRenewalInterval { get; set; } = TimeSpan.FromSeconds(10);

    /// <summary>Base delay for retryable handler failures. Defaults to two seconds.</summary>
    public TimeSpan BaseRetryDelay { get; set; } = TimeSpan.FromSeconds(2);

    /// <summary>Maximum exponential retry delay. Defaults to two minutes.</summary>
    public TimeSpan MaximumRetryDelay { get; set; } = TimeSpan.FromMinutes(2);
}
